[xtime, fs] = audioread("catscan2.wav");
t = (0:length(xtime)-1)/fs;
xtime=mean(xtime,2);
plot(t, xtime) %[output:43136d4b]
sound(xtime, fs)
%%

N = length(xtime);
X = fft(xtime);
freqs = (0:N-1)* (fs/N);
plot(N, abs(X)) %[output:0bdd2289]
abs(X) %[output:7b6cd2c4]
figure; %[output:080f2c0e]
plot(freqs, X) %[output:8dbcc191] %[output:080f2c0e]
datacursormode on; %[output:080f2c0e]

